import{at as e,n as t,ot as n,yt as r}from"./chunks/framework.dgpN-s4-.js";var i=JSON.parse(`{"title":"Greedy","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/strategies/GREEDY.html"}],["meta",{"property":"og:title","content":"Greedy | FD Cal Documentation"}],["meta",{"property":"og:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}],["meta",{"property":"og:url","content":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/strategies/GREEDY.html"}],["meta",{"name":"twitter:title","content":"Greedy | FD Cal Documentation"}],["meta",{"name":"twitter:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}]]},"headers":[],"relativePath":"strategies/GREEDY.md","filePath":"strategies/GREEDY.md","lastUpdated":1793949552000}`),a={name:`strategies/GREEDY.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<h1 id="greedy" tabindex="-1">Greedy <a class="header-anchor" href="#greedy" aria-label="Permalink to “Greedy”">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h2><p>Greedy is FD Cal&#39;s fast, rule-based baseline strategy. It makes a decision at each event date using the balances, eligible FD products, transfer fees and obligations known at that point.</p><p>It is a <strong>heuristic strategy</strong>: it uses explicit selection rules to choose a locally attractive plan instead of searching all possible future decision sequences. It can compare several plans for the current date, but it does not preserve alternative paths and evaluate their complete future outcomes.</p><p>Consequently, Greedy is fast and useful as a baseline, but it does not guarantee the globally highest net return over the full simulation period.</p><p><strong>Implementation:</strong> <code>src/strategies/greedy.js</code></p><h2 id="strategy-context-and-configuration" tabindex="-1">Strategy context and configuration <a class="header-anchor" href="#strategy-context-and-configuration" aria-label="Permalink to “Strategy context and configuration”">​</a></h2><p>Greedy is created through <code>createSession(context)</code>, using the shared simulation context supplied by <code>SimulationEngine</code>. It does not accept or own the user&#39;s simulation inputs as a separate strategy-level input contract.</p><p>The shared context provides the strategy with the FD option catalogue and the simulation-wide configuration needed for planning, including:</p><ul><li>The simulation start and effective end boundary.</li><li>Account definitions and initial balances.</li><li>Inflow and outflow schedules, which are processed by the shared runtime.</li><li>Transfer-fee configuration and the configured inflow and consolidation account IDs.</li><li>Interest compounding, leap-year and effective AIT settings.</li></ul><p>At each decision boundary, Greedy receives a read-only runtime view containing the current date, revision and account balances. It uses that snapshot together with the shared context to produce its next decision. The strategy does not independently advance dates or settle scheduled cash flows.</p><p>Account defaults and input normalization belong to the simulation/configuration layer, not to Greedy. By the time a session is created, the context contains the resolved account and configuration state. Greedy constructs one <code>FDOptionManager</code> from the context&#39;s FD options. Account eligibility is evaluated against each individual account, including its eFD capability; eFD support is not assumed to be uniform across all accounts.</p><h2 id="session-planning" tabindex="-1">Session planning <a class="header-anchor" href="#session-planning" aria-label="Permalink to “Session planning”">​</a></h2><p>The shared runtime advances the authoritative event timeline and settles inflows, FD cash flows, maturities and outflows before requesting a strategy decision. Greedy receives a deeply immutable account snapshot at each decision boundary.</p><p>Greedy evaluates the currently available balances and returns a revision-bound SPLIT, CONSOLIDATE or CARRY decision. It does not process the actual timeline, settle actual outflows, execute transfers/bookings, schedule actual cash flows or construct the result. Those operations belong to <code>SimulationRuntime</code>.</p><p>Greedy remains locally greedy: it reacts to the current runtime snapshot rather than preserving alternative complete future paths.</p><h2 id="daily-plan-generation" tabindex="-1">Daily plan generation <a class="header-anchor" href="#daily-plan-generation" aria-label="Permalink to “Daily plan generation”">​</a></h2><p>For each decision date, Greedy considers two investment plan types: <strong>SPLIT</strong> and <strong>CONSOLIDATE</strong>. If neither produces an admissible candidate, it carries the available balances forward.</p><h3 id="split" tabindex="-1">SPLIT <a class="header-anchor" href="#split" aria-label="Permalink to “SPLIT”">​</a></h3><p>Greedy evaluates each account with a balance greater than the internal epsilon threshold.</p><p>For each account:</p><ol><li>Requests eligible options from <code>FDOptionManager</code>, using the account, its full available balance, the current date and simulation end date.</li><li>Selects one option using the option-selection rules below.</li><li>Calculates the interest for the account&#39;s balance.</li><li>Marks the account as a carry if no eligible option exists.</li></ol><p>The resulting SPLIT decision requests that the runtime book each selected account balance independently. Accounts without a suitable option remain as carries.</p><p>The plan&#39;s comparison rate is the <strong>highest selected annual rate</strong> among its bookings; its comparison tenor is the <strong>shortest selected tenor</strong>. Gross interest is the sum of the selected bookings&#39; interest, and net interest is gross interest after the configured effective AIT deduction. SPLIT has no transfer fees.</p><h3 id="consolidate" tabindex="-1">CONSOLIDATE <a class="header-anchor" href="#consolidate" aria-label="Permalink to “CONSOLIDATE”">​</a></h3><p>Greedy evaluates every configured account as a possible target account.</p><p>For each target:</p><ol><li>The target&#39;s own available balance contributes to the deployable amount without a transfer.</li><li>Every other positive-balance account is considered as a transfer source.</li><li>The applicable source-to-target fee is obtained from <code>TransferFeeConfig</code>.</li><li>If a source balance is less than or equal to its transfer fee, that source is left as a carry.</li><li>Otherwise, the fee is deducted from the source amount and the net transfer contributes to the target&#39;s deployable amount.</li><li>Greedy requests eligible FD options for the target account and the aggregate deployable amount.</li><li>If an option is available, it calculates gross interest and the estimated net interest used for plan evaluation.</li></ol><p>A consolidation plan is discarded if it has no transfers, no eligible target option, or non-positive estimated net interest.</p><p>The target account&#39;s own balance is not charged a transfer fee. Each actual source-to-target transfer is charged once during execution.</p><h4 id="transfer-fee-evaluation" tabindex="-1">Transfer-fee evaluation <a class="header-anchor" href="#transfer-fee-evaluation" aria-label="Permalink to “Transfer-fee evaluation”">​</a></h4><p>The current implementation maintains two different fee totals:</p><ul><li><code>fees_today</code>: the sum of actual fees for the transfers required by the candidate plan.</li><li><code>fees_eval</code>: the estimated fee penalty subtracted when comparing the candidate&#39;s net interest.</li></ul><p>The current estimated-fee rule is:</p><table tabindex="0"><thead><tr><th>Transfer source</th><th>Consolidation target</th><th style="text-align:right;">Evaluation fee</th></tr></thead><tbody><tr><td>Main consolidation account</td><td>Another account</td><td style="text-align:right;">2 × transfer fee</td></tr><tr><td>Another account</td><td>Main consolidation account</td><td style="text-align:right;">1 × transfer fee</td></tr><tr><td>Another account</td><td>Another account</td><td style="text-align:right;">2 × transfer fee</td></tr></tbody></table><p>Here, “main” means the configured <code>consolidation_account_id</code>.</p><p>This multiplier is an evaluation assumption in the current implementation; it is <strong>not</strong> an additional fee charged during transfer execution. Actual execution deducts each transfer fee once and adds that amount once to the simulation&#39;s total transfer fees. The rationale for the estimated multiplier should be revisited if the intended model of subsequent fund repositioning changes.</p><h3 id="carry" tabindex="-1">CARRY <a class="header-anchor" href="#carry" aria-label="Permalink to “CARRY”">​</a></h3><p>If no candidate plan is available, Greedy leaves the active balances in their accounts. It also carries individual accounts when no eligible FD option fits their balance or account capabilities.</p><p>Carry is not an FD investment and earns no modelled FD interest while the balance remains idle.</p><h2 id="fd-option-selection" tabindex="-1">FD option selection <a class="header-anchor" href="#fd-option-selection" aria-label="Permalink to “FD option selection”">​</a></h2><p>Greedy uses two selection stages.</p><h3 id="select-one-option-for-an-account-or-consolidated-amount" tabindex="-1">Select one option for an account or consolidated amount <a class="header-anchor" href="#select-one-option-for-an-account-or-consolidated-amount" aria-label="Permalink to “Select one option for an account or consolidated amount”">​</a></h3><p>The <code>selectBestOption</code> function compares eligible options in this order:</p><ol><li>Higher annual interest rate.</li><li>Shorter tenor when annual rates are equal.</li><li>Prefer eFD when the annual rate and tenor are equal and the options have the same <code>economic_terms_key</code>, provided the current best option is standard.</li></ol><p>This is a rate-first rule. It does not directly select the option with the highest absolute interest amount across different tenors.</p><h3 id="efd-preference-between-equivalent-products" tabindex="-1">eFD preference between equivalent products <a class="header-anchor" href="#efd-preference-between-equivalent-products" aria-label="Permalink to “eFD preference between equivalent products”">​</a></h3><p>When ranking complete daily plans, Greedy counts selected eFD bookings for which the same account also has a standard option with matching economic terms. This count is only a late tie-breaker; it does not override a higher rate, shorter tenor or higher net interest in the preceding ranking fields.</p><h2 id="candidate-admission-and-plan-ranking" tabindex="-1">Candidate admission and plan ranking <a class="header-anchor" href="#candidate-admission-and-plan-ranking" aria-label="Permalink to “Candidate admission and plan ranking”">​</a></h2><p>Greedy first builds the SPLIT plan, if at least one account can be booked, and then generates feasible CONSOLIDATE plans.</p><p>Consolidation admission depends on whether SPLIT exists:</p><ul><li><strong>When SPLIT exists:</strong> a consolidation plan is admitted only if its rate is higher and its estimated net interest is higher; or if its rate is equal and its estimated net interest exceeds SPLIT&#39;s by more than 0.01.</li><li><strong>When SPLIT does not exist:</strong> a consolidation plan is admitted if its estimated net interest is positive.</li></ul><p>If no candidate survives, Greedy selects CARRY.</p><p>The surviving candidates are sorted lexicographically by:</p><ol><li>Higher comparison annual rate.</li><li>Shorter comparison tenor.</li><li>Higher estimated net interest.</li><li>Lower actual transfer fees for the current date.</li><li>Higher count of equivalent eFD selections.</li></ol><p>The first candidate is executed.</p><p><strong>Important consequence:</strong> net interest is not the primary ranking field. The admission rules first constrain which consolidation plans can compete; among admitted candidates, a higher-rate plan can rank ahead of a plan with higher net interest.</p><h3 id="goal-mode-status" tabindex="-1">Goal mode status <a class="header-anchor" href="#goal-mode-status" aria-label="Permalink to “Goal mode status”">​</a></h3><p>Greedy is a Scoped Range strategy only. It does not implement the earliest-achievement Goal objective. Goal mode is disabled while the project develops a dedicated Absolute R planner; Greedy&#39;s scoped selection and ranking rules are not dual-optimised.</p><h2 id="decision-contract-planning-only" tabindex="-1">Decision contract (planning only) <a class="header-anchor" href="#decision-contract-planning-only" aria-label="Permalink to “Decision contract (planning only)”">​</a></h2><p>Greedy returns a revision-bound decision describing the plan selected for the current planning snapshot. It does not execute any part of that plan.</p><ul><li><strong>SPLIT:</strong> identifies the account/FD-option/principal tuples the runtime should book independently, plus accounts that remain liquid.</li><li><strong>CONSOLIDATE:</strong> identifies the target account, source-to-target transfers, selected FD option and deployable principal. It is a proposed atomic transfer-and-booking plan, not an executed transaction.</li><li><strong>CARRY:</strong> asks the runtime to leave the current positive balances unchanged for this decision boundary.</li></ul><p>The strategy does not debit or credit authoritative balances, charge fees, create actual events, schedule cash flows, settle obligations or construct a simulation result. <code>SimulationRuntime</code> validates and executes the selected decision against the authoritative state. Invalid or stale decisions are rejected by the runtime before commit.</p><h2 id="runtime-owned-execution-and-finalization" tabindex="-1">Runtime-owned execution and finalization <a class="header-anchor" href="#runtime-owned-execution-and-finalization" aria-label="Permalink to “Runtime-owned execution and finalization”">​</a></h2><p>After Greedy returns a decision, <code>SimulationRuntime</code> owns all actual effects:</p><ul><li>Validates account references, option eligibility, balances, transfer fees and staged events.</li><li>Executes transfers and bookings atomically, including actual fee deductions.</li><li>Schedules actual FD cash-flow and maturity events.</li><li>Records the actual event ledger and updates authoritative balances.</li><li>Processes later inflows, maturities, cash flows and outflow obligations.</li></ul><p>Greedy does not perform a final sweep. After the complete simulation horizon and strategy session finish, <code>SimulationEngine</code> invokes the single simulation-wide consolidation sweep. It transfers eligible residual balances to the configured consolidation account, charges each applicable fee once, and records any remaining idle cash. This finalization is strategy-independent.</p><h2 id="financial-result-and-diagnostics" tabindex="-1">Financial result and diagnostics <a class="header-anchor" href="#financial-result-and-diagnostics" aria-label="Permalink to “Financial result and diagnostics”">​</a></h2><p><code>SimulationRuntime</code> constructs the unfinished result from actual bookings, timeline events, transfer fees, paid/outstanding outflows, account balances and validity status. <code>SimulationEngine</code> then finalizes it. AIT is applied through the configured effective AIT rate when calculating net interest and generating net cash flows.</p><p>Booking and carry events include a <code>decision_context</code> with the action and balances before the action. Greedy retains its existing empty <code>decision_log</code>; it does not expose a full trace of every candidate considered, rejected or ranked.</p><h2 id="strengths-and-limitations" tabindex="-1">Strengths and limitations <a class="header-anchor" href="#strengths-and-limitations" aria-label="Permalink to “Strengths and limitations”">​</a></h2><h3 id="strengths" tabindex="-1">Strengths <a class="header-anchor" href="#strengths" aria-label="Permalink to “Strengths”">​</a></h3><ul><li>Fast, deterministic baseline for a given input.</li><li>Considers both separate account-level bookings and account consolidation.</li><li>Uses bank-aware FD option eligibility through <code>FDOptionManager</code>.</li><li>Respects account-specific eFD capability and transfer fees.</li><li>Reacts to inflows, FD cash flows, maturities and outflow obligations as they occur.</li></ul><h3 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to “Limitations”">​</a></h3><ul><li><strong>Locally greedy:</strong> it commits to the selected plan at each date rather than comparing complete future paths.</li><li><strong>No global optimality guarantee:</strong> a locally attractive booking can prevent a better later combination.</li><li><strong>Rate-first selection:</strong> annual rate and tenor precede absolute net return in the option and plan ranking rules.</li><li><strong>Restrictive consolidation admission:</strong> a consolidation plan generally needs to beat SPLIT on both comparison rate and estimated net interest.</li><li><strong>Fee-model assumption:</strong> estimated consolidation fees can differ from actual fees charged; the multiplier is an evaluation penalty, not an execution charge.</li><li><strong>Limited decision diagnostics:</strong> the structured decision log is currently empty.</li></ul><h2 id="when-to-use-greedy" tabindex="-1">When to use Greedy <a class="header-anchor" href="#when-to-use-greedy" aria-label="Permalink to “When to use Greedy”">​</a></h2><p>Greedy is appropriate when you need a fast, deterministic plan based on the balances and eligible FD options available at each decision boundary.</p><p>It is particularly useful when:</p><ul><li>The scenario needs a quick result with low planning overhead.</li><li>The decision policy should remain simple and explainable.</li><li>Immediate rate-first selection is acceptable, even when it may not maximise total return over the full horizon.</li><li>You want a predictable baseline policy for operational use.</li></ul><p>Greedy is not appropriate when the requirement is to evaluate complete alternative future decision paths or to prove that the resulting portfolio is globally optimal. Its decisions are intentionally local, and its result should be interpreted with that limitation in mind.</p><h2 id="source-map" tabindex="-1">Source map <a class="header-anchor" href="#source-map" aria-label="Permalink to “Source map”">​</a></h2><table tabindex="0"><thead><tr><th>Concern</th><th>Implementation</th></tr></thead><tbody><tr><td>Daily SPLIT / CONSOLIDATE / CARRY planning</td><td><code>pickDailyGreedyPlan</code> and <code>GreedyStrategy.createSession</code> in <code>src/strategies/greedy.js</code></td></tr><tr><td>Actual event progression and execution</td><td><code>src/core/simulation-runtime.js</code></td></tr><tr><td>Session driving and finalization</td><td><code>src/core/simulation.js</code></td></tr><tr><td>FD option eligibility and bank grouping</td><td><code>src/fd-options/index.js</code></td></tr><tr><td>Account and transfer-fee models</td><td><code>src/core/models.js</code></td></tr><tr><td>Event and inflow models</td><td><code>src/core/events.js</code></td></tr><tr><td>Booking and simulation result models</td><td><code>src/core/results.js</code></td></tr></tbody></table>`,82)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};